sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // 1. Map segment to SAP credit segment
    var segment = current.getValue('segment') + '';
    var creditSegment = '';

    if (segment === 'Cement') creditSegment = 'GIL';
    else if (segment === 'RMC') creditSegment = 'URMX';
    else if (segment === 'BPD') creditSegment = 'GIL';

    if (!creditSegment) {
        gs.error('CLM NT SAP Writeback: Unrecognized segment "' + segment + '" for PAN ' + current.getValue('number'));
        return;
    }

    // 2. Query child site requests matching this PAN Request
    var siteGr = new GlideRecord('x_birl3_clm_nt_site_request');
    siteGr.addQuery('pan_request', current.getUniqueValue());
    siteGr.query();

    while (siteGr.next()) {
        // Parse approved_limit (strip currency prefix if present)
        var rawLimit = siteGr.getValue('approved_limit');
        if (typeof rawLimit === 'string' && rawLimit.indexOf(';') > -1) {
            rawLimit = rawLimit.split(';')[1];
        }

        // 3. Insert directly into the SAP send-back queue
        var q = new GlideRecord('x_birl3_clm_clm_servicenow_to_sap_send_back');
        q.initialize();

        q.setValue('nt_request', current.getUniqueValue());
        q.setValue('customer_type', 'non_trade');
        q.setValue('u_customer_code', siteGr.getValue('customer_site_code'));
        q.setValue('u_approved_code_limit', parseFloat(rawLimit));
        q.setValue('u_next_review_date', siteGr.getValue('proposed_next_review'));
        q.setValue('u_credit_segment', creditSegment);
        q.setValue('u_status', 'Pending');
        q.setValue('u_attempt_count', 0);

        q.insert();
    }

})(current, previous);
